CREATE TABLE Core.Currency(CurrencyCode char(3) NOT NULL CONSTRAINT PK_Currency PRIMARY KEY, CurrencyNameAr nvarchar(100) NOT NULL, CurrencyNameEn nvarchar(100) NOT NULL, MinorUnit tinyint NOT NULL CONSTRAINT DF_Currency_Minor DEFAULT(2), IsActive bit NOT NULL CONSTRAINT DF_Currency_Active DEFAULT(1), CONSTRAINT CK_Currency_Minor CHECK(MinorUnit BETWEEN 0 AND 6));
CREATE TABLE Org.Company(CompanyID int IDENTITY(1,1) NOT NULL CONSTRAINT PK_Company PRIMARY KEY, CompanyCode nvarchar(20) NOT NULL, CompanyNameAr nvarchar(200) NOT NULL, CompanyNameEn nvarchar(200) NULL, BaseCurrencyCode char(3) NOT NULL, LegalRegistrationNo nvarchar(80) NULL, IsActive bit NOT NULL CONSTRAINT DF_Company_Active DEFAULT(1), RowVer rowversion NOT NULL, CONSTRAINT UQ_Company_Code UNIQUE(CompanyCode), CONSTRAINT FK_Company_Currency FOREIGN KEY(BaseCurrencyCode) REFERENCES Core.Currency(CurrencyCode));
CREATE TABLE Core.Party(PartyID bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_Party PRIMARY KEY, CompanyID int NOT NULL, PartyCode nvarchar(40) NOT NULL, PartyNameAr nvarchar(200) NOT NULL, PartyType varchar(30) NOT NULL, TaxOrRegistrationNo nvarchar(80) NULL, IsActive bit NOT NULL CONSTRAINT DF_Party_Active DEFAULT(1), RowVer rowversion NOT NULL, CONSTRAINT FK_Party_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT UQ_Party_Code UNIQUE(CompanyID,PartyCode));
CREATE TABLE Org.Branch(BranchID int IDENTITY(1,1) NOT NULL CONSTRAINT PK_Branch PRIMARY KEY, CompanyID int NOT NULL, BranchCode nvarchar(20) NOT NULL, BranchNameAr nvarchar(200) NOT NULL, ParentBranchID int NULL, IsActive bit NOT NULL CONSTRAINT DF_Branch_Active DEFAULT(1), RowVer rowversion NOT NULL, CONSTRAINT FK_Branch_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_Branch_Parent FOREIGN KEY(ParentBranchID) REFERENCES Org.Branch(BranchID), CONSTRAINT UQ_Branch_CompanyCode UNIQUE(CompanyID,BranchCode), CONSTRAINT UQ_Branch_CompanyBranch UNIQUE(CompanyID,BranchID));
CREATE TABLE Org.FiscalYear(CompanyID int NOT NULL, FiscalYear smallint NOT NULL, StartsOn date NOT NULL, EndsOn date NOT NULL, IsClosed bit NOT NULL CONSTRAINT DF_FY_Closed DEFAULT(0), ClosedAt datetime2(0) NULL, ClosedBy bigint NULL, CONSTRAINT PK_FiscalYear PRIMARY KEY(CompanyID,FiscalYear), CONSTRAINT FK_FY_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT CK_FY_Dates CHECK(StartsOn<=EndsOn));
CREATE TABLE Org.ExchangeRate(CompanyID int NOT NULL, CurrencyCode char(3) NOT NULL, RateDate date NOT NULL, RateType varchar(20) NOT NULL, Rate decimal(19,8) NOT NULL, SourceName nvarchar(100) NULL, CONSTRAINT PK_ExchangeRate PRIMARY KEY(CompanyID,CurrencyCode,RateDate,RateType), CONSTRAINT FK_ER_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_ER_Currency FOREIGN KEY(CurrencyCode) REFERENCES Core.Currency(CurrencyCode), CONSTRAINT CK_ER_Rate CHECK(Rate>0));

CREATE TABLE Security.UserAccount(UserID bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_UserAccount PRIMARY KEY, LoginName nvarchar(100) NOT NULL, DisplayName nvarchar(200) NOT NULL, PasswordHash varbinary(512) NOT NULL, IsEnabled bit NOT NULL CONSTRAINT DF_User_Enabled DEFAULT(1), MustChangePassword bit NOT NULL CONSTRAINT DF_User_Change DEFAULT(1), CreatedAt datetime2(0) NOT NULL CONSTRAINT DF_User_Created DEFAULT(sysutcdatetime()), RowVer rowversion NOT NULL, CONSTRAINT UQ_User_Login UNIQUE(LoginName));
CREATE TABLE Security.Role(RoleID int IDENTITY(1,1) NOT NULL CONSTRAINT PK_Role PRIMARY KEY, CompanyID int NULL, RoleCode nvarchar(60) NOT NULL, RoleNameAr nvarchar(160) NOT NULL, IsSystemRole bit NOT NULL CONSTRAINT DF_Role_System DEFAULT(0), CONSTRAINT FK_Role_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID));
CREATE TABLE Security.Permission(PermissionID int IDENTITY(1,1) NOT NULL CONSTRAINT PK_Permission PRIMARY KEY, SystemNo tinyint NOT NULL, PermissionCode nvarchar(120) NOT NULL, PermissionNameAr nvarchar(200) NOT NULL, CONSTRAINT UQ_Permission UNIQUE(SystemNo,PermissionCode), CONSTRAINT CK_Permission_System CHECK(SystemNo BETWEEN 1 AND 28));
CREATE TABLE Security.UserCompanyScope(ScopeID bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_UserCompanyScope PRIMARY KEY, UserID bigint NOT NULL, CompanyID int NOT NULL, BranchID int NULL, IsDefault bit NOT NULL CONSTRAINT DF_UCS_Default DEFAULT(0), CONSTRAINT FK_UCS_User FOREIGN KEY(UserID) REFERENCES Security.UserAccount(UserID), CONSTRAINT FK_UCS_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_UCS_Branch FOREIGN KEY(CompanyID,BranchID) REFERENCES Org.Branch(CompanyID,BranchID));
CREATE UNIQUE INDEX UX_UCS_CompanyScope ON Security.UserCompanyScope(UserID,CompanyID) WHERE BranchID IS NULL;
CREATE UNIQUE INDEX UX_UCS_BranchScope ON Security.UserCompanyScope(UserID,CompanyID,BranchID) WHERE BranchID IS NOT NULL;
CREATE TABLE Security.UserRole(UserRoleID bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_UserRole PRIMARY KEY, UserID bigint NOT NULL, RoleID int NOT NULL, CompanyID int NULL, BranchID int NULL, GrantedAt datetime2(0) NOT NULL CONSTRAINT DF_UR_At DEFAULT(sysutcdatetime()), CONSTRAINT FK_UR_User FOREIGN KEY(UserID) REFERENCES Security.UserAccount(UserID), CONSTRAINT FK_UR_Role FOREIGN KEY(RoleID) REFERENCES Security.Role(RoleID), CONSTRAINT FK_UR_Branch FOREIGN KEY(CompanyID,BranchID) REFERENCES Org.Branch(CompanyID,BranchID));
CREATE UNIQUE INDEX UX_UserRole_Global ON Security.UserRole(UserID,RoleID) WHERE CompanyID IS NULL AND BranchID IS NULL;
CREATE UNIQUE INDEX UX_UserRole_Company ON Security.UserRole(UserID,RoleID,CompanyID) WHERE CompanyID IS NOT NULL AND BranchID IS NULL;
CREATE UNIQUE INDEX UX_UserRole_Branch ON Security.UserRole(UserID,RoleID,CompanyID,BranchID) WHERE BranchID IS NOT NULL;
CREATE TABLE Security.RolePermission(RoleID int NOT NULL, PermissionID int NOT NULL, CanCreate bit NOT NULL DEFAULT(0), CanRead bit NOT NULL DEFAULT(0), CanUpdate bit NOT NULL DEFAULT(0), CanDelete bit NOT NULL DEFAULT(0), CanApprove bit NOT NULL DEFAULT(0), CanPost bit NOT NULL DEFAULT(0), CONSTRAINT PK_RolePermission PRIMARY KEY(RoleID,PermissionID), CONSTRAINT FK_RP_Role FOREIGN KEY(RoleID) REFERENCES Security.Role(RoleID), CONSTRAINT FK_RP_Permission FOREIGN KEY(PermissionID) REFERENCES Security.Permission(PermissionID));

CREATE TABLE Workflow.Definition(WorkflowID bigint IDENTITY(1,1) PRIMARY KEY, CompanyID int NULL, SystemNo tinyint NOT NULL, WorkflowCode nvarchar(80) NOT NULL, VersionNo int NOT NULL, IsActive bit NOT NULL DEFAULT(0), CONSTRAINT UQ_Workflow UNIQUE(CompanyID,SystemNo,WorkflowCode,VersionNo));
CREATE TABLE Workflow.State(WorkflowID bigint NOT NULL, StateCode nvarchar(30) NOT NULL, StateNameAr nvarchar(100) NOT NULL, IsTerminal bit NOT NULL DEFAULT(0), CONSTRAINT PK_WorkflowState PRIMARY KEY(WorkflowID,StateCode), CONSTRAINT FK_WS_Def FOREIGN KEY(WorkflowID) REFERENCES Workflow.Definition(WorkflowID));
CREATE TABLE Workflow.Transition(WorkflowID bigint NOT NULL, FromState nvarchar(30) NOT NULL, ToState nvarchar(30) NOT NULL, PermissionID int NOT NULL, RequiresReason bit NOT NULL DEFAULT(0), CONSTRAINT PK_WorkflowTransition PRIMARY KEY(WorkflowID,FromState,ToState), CONSTRAINT FK_WT_From FOREIGN KEY(WorkflowID,FromState) REFERENCES Workflow.State(WorkflowID,StateCode), CONSTRAINT FK_WT_To FOREIGN KEY(WorkflowID,ToState) REFERENCES Workflow.State(WorkflowID,StateCode), CONSTRAINT FK_WT_Perm FOREIGN KEY(PermissionID) REFERENCES Security.Permission(PermissionID));
CREATE TABLE Workflow.ApprovalInstance(ApprovalID bigint IDENTITY(1,1) PRIMARY KEY, CompanyID int NOT NULL, SystemNo tinyint NOT NULL, EntityType nvarchar(100) NOT NULL, EntityID bigint NOT NULL, CurrentStep int NOT NULL, StatusCode varchar(20) NOT NULL, StartedAt datetime2(0) NOT NULL DEFAULT(sysutcdatetime()), CompletedAt datetime2(0) NULL, RowVer rowversion NOT NULL, CONSTRAINT FK_Approval_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID));
CREATE TABLE Workflow.ApprovalAction(ActionID bigint IDENTITY(1,1) PRIMARY KEY, ApprovalID bigint NOT NULL, StepNo int NOT NULL, ActorUserID bigint NOT NULL, ActionCode varchar(20) NOT NULL, ActionAt datetime2(0) NOT NULL DEFAULT(sysutcdatetime()), Comments nvarchar(1000) NULL, CONSTRAINT FK_AA_Instance FOREIGN KEY(ApprovalID) REFERENCES Workflow.ApprovalInstance(ApprovalID), CONSTRAINT FK_AA_User FOREIGN KEY(ActorUserID) REFERENCES Security.UserAccount(UserID));
CREATE TABLE Audit.Event(EventID bigint IDENTITY(1,1) PRIMARY KEY, CompanyID int NULL, UserID bigint NULL, SystemNo tinyint NULL, EntityName sysname NOT NULL, EntityKey nvarchar(300) NOT NULL, ActionCode varchar(20) NOT NULL, OccurredAt datetime2(3) NOT NULL DEFAULT(sysutcdatetime()), CorrelationID uniqueidentifier NULL, BeforeJson nvarchar(max) NULL, AfterJson nvarchar(max) NULL, CONSTRAINT FK_Audit_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_Audit_User FOREIGN KEY(UserID) REFERENCES Security.UserAccount(UserID), CONSTRAINT CK_Audit_Json CHECK((BeforeJson IS NULL OR ISJSON(BeforeJson)=1) AND (AfterJson IS NULL OR ISJSON(AfterJson)=1)));
CREATE INDEX IX_Audit_Entity ON Audit.Event(CompanyID,EntityName,EntityKey,OccurredAt DESC);
CREATE TABLE Document.Document(DocumentID bigint IDENTITY(1,1) PRIMARY KEY, CompanyID int NOT NULL, DocumentNo nvarchar(80) NOT NULL, DocumentType nvarchar(60) NOT NULL, Title nvarchar(300) NOT NULL, OwnerSystemNo tinyint NOT NULL, EntityType nvarchar(100) NULL, EntityID bigint NULL, IsArchived bit NOT NULL DEFAULT(0), CreatedAt datetime2(0) NOT NULL DEFAULT(sysutcdatetime()), CONSTRAINT FK_Doc_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT UQ_Doc_No UNIQUE(CompanyID,DocumentNo));
CREATE TABLE Document.DocumentVersion(VersionID bigint IDENTITY(1,1) PRIMARY KEY, DocumentID bigint NOT NULL, VersionNo int NOT NULL, RelativePath nvarchar(700) NOT NULL, FileName nvarchar(260) NOT NULL, ContentLength bigint NOT NULL, Sha256 char(64) NOT NULL, MimeType nvarchar(150) NULL, UploadedAt datetime2(0) NOT NULL DEFAULT(sysutcdatetime()), UploadedBy bigint NOT NULL, CONSTRAINT FK_DV_Doc FOREIGN KEY(DocumentID) REFERENCES Document.Document(DocumentID), CONSTRAINT FK_DV_User FOREIGN KEY(UploadedBy) REFERENCES Security.UserAccount(UserID), CONSTRAINT UQ_DV_Version UNIQUE(DocumentID,VersionNo), CONSTRAINT CK_DV_Length CHECK(ContentLength>=0), CONSTRAINT CK_DV_SHA CHECK(Sha256 NOT LIKE '%[^0-9A-Fa-f]%'));
CREATE TABLE Integration.OutboxMessage(MessageID uniqueidentifier NOT NULL PRIMARY KEY DEFAULT(newid()), CompanyID int NOT NULL, SourceSystemNo tinyint NOT NULL, EventType nvarchar(150) NOT NULL, Payload nvarchar(max) NOT NULL, CreatedAt datetime2(3) NOT NULL DEFAULT(sysutcdatetime()), PublishedAt datetime2(3) NULL, RetryCount int NOT NULL DEFAULT(0), CONSTRAINT FK_Outbox_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT CK_Outbox_Json CHECK(ISJSON(Payload)=1));

-- 1. الحسابات العامة / Accounting

CREATE TABLE [Accounting].[Journal](JournalID bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_Acc_Journal PRIMARY KEY, CompanyID int NOT NULL, BranchID int NULL, Code nvarchar(40) NOT NULL, NameAr nvarchar(200) NOT NULL, StateCode varchar(20) NOT NULL, CreatedAt datetime2(0) NOT NULL CONSTRAINT DF_Acc_Journal_Created DEFAULT(sysutcdatetime()), CreatedBy bigint NOT NULL, RowVer rowversion NOT NULL, CONSTRAINT FK_Acc_Journal_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_Acc_Journal_Branch FOREIGN KEY(CompanyID,BranchID) REFERENCES Org.Branch(CompanyID,BranchID), CONSTRAINT FK_Acc_Journal_User FOREIGN KEY(CreatedBy) REFERENCES Security.UserAccount(UserID), CONSTRAINT UQ_Acc_Journal_Code UNIQUE(CompanyID,Code), CONSTRAINT UQ_Acc_Journal_CompanyID UNIQUE(CompanyID,JournalID));

CREATE TABLE [Accounting].[JournalLine](JournalLineID bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_Acc_JournalLine PRIMARY KEY, CompanyID int NOT NULL, JournalID bigint NOT NULL, LineNo int NOT NULL, Description nvarchar(500) NOT NULL, Quantity decimal(19,4) NULL, UnitCode nvarchar(20) NULL, UnitPrice decimal(19,4) NULL, Amount decimal(19,4) NULL, CurrencyCode char(3) NULL, CONSTRAINT FK_Acc_JournalLine_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_Acc_JournalLine_Journal FOREIGN KEY(CompanyID,JournalID) REFERENCES [Accounting].[Journal](CompanyID,JournalID), CONSTRAINT FK_Acc_JournalLine_Currency FOREIGN KEY(CurrencyCode) REFERENCES Core.Currency(CurrencyCode), CONSTRAINT UQ_Acc_JournalLine_Line UNIQUE(JournalID,LineNo), CONSTRAINT CK_Acc_JournalLine_Qty CHECK(Quantity IS NULL OR Quantity>=0));

CREATE TABLE [Accounting].[FiscalPeriod](FiscalPeriodID bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_Acc_FiscalPeriod PRIMARY KEY, CompanyID int NOT NULL, JournalID bigint NOT NULL, EventDate date NOT NULL, EventType nvarchar(40) NOT NULL, Amount decimal(19,4) NULL, CurrencyCode char(3) NULL, ReferenceNo nvarchar(80) NULL, Notes nvarchar(1000) NULL, CreatedAt datetime2(0) NOT NULL DEFAULT(sysutcdatetime()), CONSTRAINT FK_Acc_FiscalPeriod_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_Acc_FiscalPeriod_Journal FOREIGN KEY(CompanyID,JournalID) REFERENCES [Accounting].[Journal](CompanyID,JournalID), CONSTRAINT FK_Acc_FiscalPeriod_Currency FOREIGN KEY(CurrencyCode) REFERENCES Core.Currency(CurrencyCode));

CREATE INDEX IX_Acc_Journal_State ON [Accounting].[Journal](CompanyID,StateCode,CreatedAt DESC);

-- 2. الحسابات الدائنة / AccountsPayable

CREATE TABLE [AccountsPayable].[SupplierInvoice](SupplierInvoiceID bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_AP_SupplierInvoice PRIMARY KEY, CompanyID int NOT NULL, BranchID int NULL, Code nvarchar(40) NOT NULL, NameAr nvarchar(200) NOT NULL, StateCode varchar(20) NOT NULL, CreatedAt datetime2(0) NOT NULL CONSTRAINT DF_AP_SupplierInvoice_Created DEFAULT(sysutcdatetime()), CreatedBy bigint NOT NULL, RowVer rowversion NOT NULL, CONSTRAINT FK_AP_SupplierInvoice_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_AP_SupplierInvoice_Branch FOREIGN KEY(CompanyID,BranchID) REFERENCES Org.Branch(CompanyID,BranchID), CONSTRAINT FK_AP_SupplierInvoice_User FOREIGN KEY(CreatedBy) REFERENCES Security.UserAccount(UserID), CONSTRAINT UQ_AP_SupplierInvoice_Code UNIQUE(CompanyID,Code), CONSTRAINT UQ_AP_SupplierInvoice_CompanyID UNIQUE(CompanyID,SupplierInvoiceID));

CREATE TABLE [AccountsPayable].[SupplierInvoiceLine](SupplierInvoiceLineID bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_AP_SupplierInvoiceLine PRIMARY KEY, CompanyID int NOT NULL, SupplierInvoiceID bigint NOT NULL, LineNo int NOT NULL, Description nvarchar(500) NOT NULL, Quantity decimal(19,4) NULL, UnitCode nvarchar(20) NULL, UnitPrice decimal(19,4) NULL, Amount decimal(19,4) NULL, CurrencyCode char(3) NULL, CONSTRAINT FK_AP_SupplierInvoiceLine_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_AP_SupplierInvoiceLine_SupplierInvoice FOREIGN KEY(CompanyID,SupplierInvoiceID) REFERENCES [AccountsPayable].[SupplierInvoice](CompanyID,SupplierInvoiceID), CONSTRAINT FK_AP_SupplierInvoiceLine_Currency FOREIGN KEY(CurrencyCode) REFERENCES Core.Currency(CurrencyCode), CONSTRAINT UQ_AP_SupplierInvoiceLine_Line UNIQUE(SupplierInvoiceID,LineNo), CONSTRAINT CK_AP_SupplierInvoiceLine_Qty CHECK(Quantity IS NULL OR Quantity>=0));

CREATE TABLE [AccountsPayable].[SupplierPayment](SupplierPaymentID bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_AP_SupplierPayment PRIMARY KEY, CompanyID int NOT NULL, SupplierInvoiceID bigint NOT NULL, EventDate date NOT NULL, EventType nvarchar(40) NOT NULL, Amount decimal(19,4) NULL, CurrencyCode char(3) NULL, ReferenceNo nvarchar(80) NULL, Notes nvarchar(1000) NULL, CreatedAt datetime2(0) NOT NULL DEFAULT(sysutcdatetime()), CONSTRAINT FK_AP_SupplierPayment_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_AP_SupplierPayment_SupplierInvoice FOREIGN KEY(CompanyID,SupplierInvoiceID) REFERENCES [AccountsPayable].[SupplierInvoice](CompanyID,SupplierInvoiceID), CONSTRAINT FK_AP_SupplierPayment_Currency FOREIGN KEY(CurrencyCode) REFERENCES Core.Currency(CurrencyCode));

CREATE INDEX IX_AP_SupplierInvoice_State ON [AccountsPayable].[SupplierInvoice](CompanyID,StateCode,CreatedAt DESC);

-- 3. الحسابات المدينة / AccountsReceivable

CREATE TABLE [AccountsReceivable].[CustomerInvoice](CustomerInvoiceID bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_AR_CustomerInvoice PRIMARY KEY, CompanyID int NOT NULL, BranchID int NULL, Code nvarchar(40) NOT NULL, NameAr nvarchar(200) NOT NULL, StateCode varchar(20) NOT NULL, CreatedAt datetime2(0) NOT NULL CONSTRAINT DF_AR_CustomerInvoice_Created DEFAULT(sysutcdatetime()), CreatedBy bigint NOT NULL, RowVer rowversion NOT NULL, CONSTRAINT FK_AR_CustomerInvoice_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_AR_CustomerInvoice_Branch FOREIGN KEY(CompanyID,BranchID) REFERENCES Org.Branch(CompanyID,BranchID), CONSTRAINT FK_AR_CustomerInvoice_User FOREIGN KEY(CreatedBy) REFERENCES Security.UserAccount(UserID), CONSTRAINT UQ_AR_CustomerInvoice_Code UNIQUE(CompanyID,Code), CONSTRAINT UQ_AR_CustomerInvoice_CompanyID UNIQUE(CompanyID,CustomerInvoiceID));

CREATE TABLE [AccountsReceivable].[CustomerInvoiceLine](CustomerInvoiceLineID bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_AR_CustomerInvoiceLine PRIMARY KEY, CompanyID int NOT NULL, CustomerInvoiceID bigint NOT NULL, LineNo int NOT NULL, Description nvarchar(500) NOT NULL, Quantity decimal(19,4) NULL, UnitCode nvarchar(20) NULL, UnitPrice decimal(19,4) NULL, Amount decimal(19,4) NULL, CurrencyCode char(3) NULL, CONSTRAINT FK_AR_CustomerInvoiceLine_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_AR_CustomerInvoiceLine_CustomerInvoice FOREIGN KEY(CompanyID,CustomerInvoiceID) REFERENCES [AccountsReceivable].[CustomerInvoice](CompanyID,CustomerInvoiceID), CONSTRAINT FK_AR_CustomerInvoiceLine_Currency FOREIGN KEY(CurrencyCode) REFERENCES Core.Currency(CurrencyCode), CONSTRAINT UQ_AR_CustomerInvoiceLine_Line UNIQUE(CustomerInvoiceID,LineNo), CONSTRAINT CK_AR_CustomerInvoiceLine_Qty CHECK(Quantity IS NULL OR Quantity>=0));

CREATE TABLE [AccountsReceivable].[CustomerReceipt](CustomerReceiptID bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_AR_CustomerReceipt PRIMARY KEY, CompanyID int NOT NULL, CustomerInvoiceID bigint NOT NULL, EventDate date NOT NULL, EventType nvarchar(40) NOT NULL, Amount decimal(19,4) NULL, CurrencyCode char(3) NULL, ReferenceNo nvarchar(80) NULL, Notes nvarchar(1000) NULL, CreatedAt datetime2(0) NOT NULL DEFAULT(sysutcdatetime()), CONSTRAINT FK_AR_CustomerReceipt_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_AR_CustomerReceipt_CustomerInvoice FOREIGN KEY(CompanyID,CustomerInvoiceID) REFERENCES [AccountsReceivable].[CustomerInvoice](CompanyID,CustomerInvoiceID), CONSTRAINT FK_AR_CustomerReceipt_Currency FOREIGN KEY(CurrencyCode) REFERENCES Core.Currency(CurrencyCode));

CREATE INDEX IX_AR_CustomerInvoice_State ON [AccountsReceivable].[CustomerInvoice](CompanyID,StateCode,CreatedAt DESC);

-- 4. الخزينة والمصارف / TreasuryManagement

