-- Project scheduling and earned value extensions
CREATE TABLE ProjectManagement.ActivityRelationship(RelationshipID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, PredecessorActivityID bigint NOT NULL, SuccessorActivityID bigint NOT NULL, RelationshipType varchar(2) NOT NULL, LagHours decimal(12,2) NOT NULL DEFAULT(0), CONSTRAINT FK_PAR_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT CK_PAR_Type CHECK(RelationshipType IN('FS','SS','FF','SF')), CONSTRAINT CK_PAR_NoSelf CHECK(PredecessorActivityID<>SuccessorActivityID), CONSTRAINT FK_PAR_Predecessor FOREIGN KEY(CompanyID,PredecessorActivityID) REFERENCES ProjectManagement.ScheduleActivity(CompanyID,ScheduleActivityID), CONSTRAINT FK_PAR_Successor FOREIGN KEY(CompanyID,SuccessorActivityID) REFERENCES ProjectManagement.ScheduleActivity(CompanyID,ScheduleActivityID));
CREATE TABLE ProjectManagement.ScheduleCalendar(CalendarID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, CalendarName nvarchar(120) NOT NULL, TimeZoneId nvarchar(80) NOT NULL, HoursPerDay decimal(5,2) NOT NULL, CONSTRAINT FK_PCal_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT CK_PCal_Hours CHECK(HoursPerDay BETWEEN 0 AND 24));
CREATE TABLE ProjectManagement.CalendarException(ExceptionID bigint IDENTITY PRIMARY KEY, CalendarID bigint NOT NULL, ExceptionDate date NOT NULL, IsWorkingDay bit NOT NULL, WorkingHours decimal(5,2) NOT NULL DEFAULT(0), Description nvarchar(200) NULL, CONSTRAINT FK_PCE_Calendar FOREIGN KEY(CalendarID) REFERENCES ProjectManagement.ScheduleCalendar(CalendarID), CONSTRAINT UQ_PCE_Date UNIQUE(CalendarID,ExceptionDate));
CREATE TABLE ProjectManagement.Baseline(BaselineID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, ProjectID bigint NOT NULL, BaselineNo int NOT NULL, ApprovedAt datetime2(0) NOT NULL, ApprovedBy bigint NOT NULL, IsCurrent bit NOT NULL DEFAULT(0), CONSTRAINT FK_PB_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_PB_User FOREIGN KEY(ApprovedBy) REFERENCES Security.UserAccount(UserID), CONSTRAINT FK_PB_Project FOREIGN KEY(CompanyID,ProjectID) REFERENCES ProjectManagement.Project(CompanyID,ProjectID), CONSTRAINT UQ_PB_No UNIQUE(ProjectID,BaselineNo));
CREATE TABLE ProjectManagement.ActivityProgress(ProgressID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, ActivityID bigint NOT NULL, DataDate date NOT NULL, PhysicalPercent decimal(7,4) NOT NULL, ActualStart date NULL, ActualFinish date NULL, RemainingDuration decimal(12,2) NULL, EV decimal(19,4) NULL, AC decimal(19,4) NULL, PV decimal(19,4) NULL, CONSTRAINT FK_PProg_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT UQ_PProg UNIQUE(ActivityID,DataDate), CONSTRAINT CK_PProg_Percent CHECK(PhysicalPercent BETWEEN 0 AND 100), CONSTRAINT FK_PProg_Activity FOREIGN KEY(CompanyID,ActivityID) REFERENCES ProjectManagement.ScheduleActivity(CompanyID,ScheduleActivityID));
CREATE TABLE ProjectManagement.ResourceAssignment(AssignmentID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, ActivityID bigint NOT NULL, ResourceCode nvarchar(50) NOT NULL, PlannedUnits decimal(19,4) NOT NULL, ActualUnits decimal(19,4) NOT NULL DEFAULT(0), StartDate date NOT NULL, FinishDate date NOT NULL, CONSTRAINT FK_PRA_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT CK_PRA_Dates CHECK(StartDate<=FinishDate), CONSTRAINT FK_PRA_Activity FOREIGN KEY(CompanyID,ActivityID) REFERENCES ProjectManagement.ScheduleActivity(CompanyID,ScheduleActivityID));
CREATE TABLE ProjectManagement.Risk(RiskID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, ProjectID bigint NOT NULL, RiskCode nvarchar(40) NOT NULL, Description nvarchar(1000) NOT NULL, Probability decimal(5,2) NOT NULL, Impact decimal(5,2) NOT NULL, OwnerUserID bigint NOT NULL, ResponsePlan nvarchar(2000) NULL, StatusCode varchar(20) NOT NULL, CONSTRAINT FK_PRisk_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_PRisk_Owner FOREIGN KEY(OwnerUserID) REFERENCES Security.UserAccount(UserID), CONSTRAINT FK_PRisk_Project FOREIGN KEY(CompanyID,ProjectID) REFERENCES ProjectManagement.Project(CompanyID,ProjectID), CONSTRAINT CK_PRisk_P CHECK(Probability BETWEEN 0 AND 100), CONSTRAINT CK_PRisk_I CHECK(Impact BETWEEN 0 AND 100));
CREATE TABLE ProjectManagement.ChangeRequest(ChangeRequestID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, ProjectID bigint NOT NULL, ChangeNo nvarchar(40) NOT NULL, ChangeDescription nvarchar(1500) NOT NULL, ScheduleImpactDays int NULL, CostImpact decimal(19,4) NULL, StatusCode varchar(20) NOT NULL, SubmittedAt datetime2(0) NOT NULL DEFAULT(sysutcdatetime()), CONSTRAINT FK_PCR_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_PCR_Project FOREIGN KEY(CompanyID,ProjectID) REFERENCES ProjectManagement.Project(CompanyID,ProjectID), CONSTRAINT UQ_PCR_No UNIQUE(CompanyID,ChangeNo));
-- Contract commercial controls
CREATE TABLE ContractManagement.ContractGuarantee(GuaranteeID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, ContractID bigint NOT NULL, GuaranteeType varchar(30) NOT NULL, Issuer nvarchar(200) NOT NULL, GuaranteeNo nvarchar(80) NOT NULL, Amount decimal(19,4) NOT NULL, CurrencyCode char(3) NOT NULL, IssuedOn date NOT NULL, ExpiresOn date NOT NULL, StatusCode varchar(20) NOT NULL, CONSTRAINT FK_CG_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_CG_Currency FOREIGN KEY(CurrencyCode) REFERENCES Core.Currency(CurrencyCode), CONSTRAINT CK_CG_Dates CHECK(IssuedOn<=ExpiresOn), CONSTRAINT CK_CG_Amount CHECK(Amount>0));
CREATE TABLE ContractManagement.CertificateDeduction(DeductionID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, CertificateID bigint NOT NULL, DeductionType varchar(30) NOT NULL, BasisAmount decimal(19,4) NOT NULL, Rate decimal(9,6) NULL, DeductionAmount decimal(19,4) NOT NULL, CONSTRAINT FK_CD_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT CK_CD_Amount CHECK(DeductionAmount>=0));
CREATE TABLE ContractManagement.ContractChange(ChangeID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, ContractID bigint NOT NULL, ChangeNo nvarchar(40) NOT NULL, ChangeType varchar(30) NOT NULL, Description nvarchar(1500) NOT NULL, ApprovedValue decimal(19,4) NULL, ApprovedDays int NULL, EffectiveDate date NULL, StatusCode varchar(20) NOT NULL, CONSTRAINT FK_CC_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT UQ_CC_No UNIQUE(CompanyID,ChangeNo));
-- Property development / sales / leasing within existing systems (no 29th system)
CREATE TABLE ProjectManagement.PropertySite(PropertySiteID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, ProjectID bigint NOT NULL, SiteCode nvarchar(40) NOT NULL, SiteName nvarchar(200) NOT NULL, LandAreaSqM decimal(19,4) NULL, LandTitleRef nvarchar(100) NULL, GeoReference nvarchar(200) NULL, CONSTRAINT FK_PropertySite_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_PropertySite_Project FOREIGN KEY(CompanyID,ProjectID) REFERENCES ProjectManagement.Project(CompanyID,ProjectID), CONSTRAINT UQ_PropertySite_Code UNIQUE(CompanyID,SiteCode), CONSTRAINT UQ_PropertySite_CompanyID UNIQUE(CompanyID,PropertySiteID));
CREATE TABLE ProjectManagement.PropertyBuilding(BuildingID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, PropertySiteID bigint NOT NULL, BuildingCode nvarchar(40) NOT NULL, BuildingName nvarchar(200) NOT NULL, FloorCount int NOT NULL, GrossAreaSqM decimal(19,4) NULL, CONSTRAINT FK_PBuilding_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_PBuilding_Site FOREIGN KEY(CompanyID,PropertySiteID) REFERENCES ProjectManagement.PropertySite(CompanyID,PropertySiteID), CONSTRAINT CK_PBuilding_Floors CHECK(FloorCount>=0), CONSTRAINT UQ_PBuilding_Code UNIQUE(PropertySiteID,BuildingCode), CONSTRAINT UQ_PBuilding_CompanyID UNIQUE(CompanyID,BuildingID));
CREATE TABLE ProjectManagement.PropertyUnit(UnitID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, BuildingID bigint NOT NULL, UnitCode nvarchar(40) NOT NULL, FloorNo int NULL, UnitType varchar(30) NOT NULL, AreaSqM decimal(19,4) NOT NULL, OwnershipStatus varchar(20) NOT NULL, AvailabilityStatus varchar(20) NOT NULL, CONSTRAINT FK_PUnit_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_PUnit_Building FOREIGN KEY(CompanyID,BuildingID) REFERENCES ProjectManagement.PropertyBuilding(CompanyID,BuildingID), CONSTRAINT CK_PUnit_Area CHECK(AreaSqM>0), CONSTRAINT UQ_PUnit_Code UNIQUE(BuildingID,UnitCode), CONSTRAINT UQ_PUnit_CompanyID UNIQUE(CompanyID,UnitID));
CREATE TABLE SalesMarketing.PropertyDeal(DealID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, UnitID bigint NOT NULL, PartyID bigint NOT NULL, DealType varchar(20) NOT NULL, DealDate date NOT NULL, TotalValue decimal(19,4) NOT NULL, CurrencyCode char(3) NOT NULL, StatusCode varchar(20) NOT NULL, CONSTRAINT FK_PD_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_PD_Currency FOREIGN KEY(CurrencyCode) REFERENCES Core.Currency(CurrencyCode), CONSTRAINT FK_PD_Party FOREIGN KEY(CompanyID,PartyID) REFERENCES Core.Party(CompanyID,PartyID), CONSTRAINT FK_PD_Unit FOREIGN KEY(CompanyID,UnitID) REFERENCES ProjectManagement.PropertyUnit(CompanyID,UnitID), CONSTRAINT UQ_PD_CompanyID UNIQUE(CompanyID,DealID), CONSTRAINT CK_PD_Type CHECK(DealType IN('SALE','LEASE')), CONSTRAINT CK_PD_Value CHECK(TotalValue>=0));
CREATE TABLE SalesMarketing.DealInstallment(InstallmentID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, DealID bigint NOT NULL, InstallmentNo int NOT NULL, DueDate date NOT NULL, Amount decimal(19,4) NOT NULL, PaidAmount decimal(19,4) NOT NULL DEFAULT(0), StatusCode varchar(20) NOT NULL, CONSTRAINT FK_DI_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_DI_Deal FOREIGN KEY(CompanyID,DealID) REFERENCES SalesMarketing.PropertyDeal(CompanyID,DealID), CONSTRAINT UQ_DI_No UNIQUE(DealID,InstallmentNo), CONSTRAINT CK_DI_Amounts CHECK(Amount>=0 AND PaidAmount>=0 AND PaidAmount<=Amount));

-- Inventory valuation: FIFO and moving weighted average only; LIFO is prohibited.
CREATE TABLE Warehouses.ValuationPolicy(PolicyID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, WarehouseID bigint NULL, ItemID bigint NULL, ValuationMethod varchar(20) NOT NULL, EffectiveFrom date NOT NULL, EffectiveTo date NULL, CONSTRAINT FK_VP_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT CK_VP_Method CHECK(ValuationMethod IN('FIFO','WEIGHTED_AVERAGE')), CONSTRAINT CK_VP_Dates CHECK(EffectiveTo IS NULL OR EffectiveFrom<=EffectiveTo));
CREATE TABLE Warehouses.InventoryCostLayer(CostLayerID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, ItemID bigint NOT NULL, WarehouseID bigint NOT NULL, ReceiptTransactionID bigint NOT NULL, ReceivedAt datetime2(0) NOT NULL, OriginalQty decimal(19,4) NOT NULL, RemainingQty decimal(19,4) NOT NULL, UnitCost decimal(19,6) NOT NULL, CurrencyCode char(3) NOT NULL, CONSTRAINT FK_ICL_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_ICL_Currency FOREIGN KEY(CurrencyCode) REFERENCES Core.Currency(CurrencyCode), CONSTRAINT CK_ICL_Qty CHECK(OriginalQty>=0 AND RemainingQty>=0 AND RemainingQty<=OriginalQty));

CREATE TABLE Core.DocumentStateTransition(FromState tinyint NOT NULL, ToState tinyint NOT NULL, RequiresSystemContext bit NOT NULL DEFAULT(0), ContextKey sysname NULL, CONSTRAINT PK_DocStateTransition PRIMARY KEY(FromState,ToState));
INSERT Core.DocumentStateTransition(FromState,ToState,RequiresSystemContext,ContextKey) VALUES (0,1,0,NULL),(1,2,0,NULL),(1,3,0,NULL),(2,1,0,NULL),(3,4,0,NULL),(3,5,0,NULL),(4,2,0,NULL),(4,3,0,NULL),(5,6,0,NULL),(5,7,0,NULL),(6,4,0,NULL),(6,5,0,NULL),(2,0,1,N'Wrh.AutoGen');
