-- Financial posting guard contract: posting to the general ledger is allowed only on transition into state 7.
-- State 7 is terminal; corrections must be represented by a separate reversing/correcting transaction.
-- Implement posting through one transactional stored procedure per source document family; never post from UI/API.
CREATE TABLE Accounting.PostingBatch(PostingBatchID bigint IDENTITY PRIMARY KEY, CompanyID int NOT NULL, SourceSystemNo tinyint NOT NULL, SourceEntity nvarchar(100) NOT NULL, SourceEntityID bigint NOT NULL, PostedAt datetime2(0) NOT NULL DEFAULT(sysutcdatetime()), PostedBy bigint NOT NULL, IdempotencyKey nvarchar(120) NOT NULL, CONSTRAINT FK_PostBatch_Company FOREIGN KEY(CompanyID) REFERENCES Org.Company(CompanyID), CONSTRAINT FK_PostBatch_User FOREIGN KEY(PostedBy) REFERENCES Security.UserAccount(UserID), CONSTRAINT UQ_PostBatch_Idem UNIQUE(CompanyID,IdempotencyKey));
GO

