-- Operational views
CREATE VIEW Core.vw_CompanyBaseCurrency AS SELECT c.CompanyID,c.CompanyCode,c.CompanyNameAr,c.BaseCurrencyCode,cur.CurrencyNameAr FROM Org.Company c JOIN Core.Currency cur ON cur.CurrencyCode=c.BaseCurrencyCode;
GO
CREATE VIEW Audit.vw_AuditRecent AS SELECT TOP(1000) EventID,CompanyID,UserID,SystemNo,EntityName,EntityKey,ActionCode,OccurredAt,CorrelationID FROM Audit.Event ORDER BY OccurredAt DESC;
GO

-- Deployment validation procedure (metadata-level).
CREATE PROCEDURE Core.usp_ValidateSchema AS BEGIN SET NOCOUNT ON; DECLARE @MissingFK int=(SELECT COUNT(*) FROM sys.foreign_keys WHERE is_not_trusted=1); DECLARE @Disabled int=(SELECT COUNT(*) FROM sys.foreign_keys WHERE is_disabled=1); SELECT (SELECT COUNT(*) FROM sys.tables WHERE is_ms_shipped=0) AS UserTables,(SELECT COUNT(*) FROM sys.foreign_keys) AS ForeignKeys,@MissingFK AS UntrustedForeignKeys,@Disabled AS DisabledForeignKeys; IF @Disabled>0 THROW 51000,'Disabled foreign keys detected.',1; END;
GO
